115	    /** Add a claim as above, carrying the tags typed comma separated (blank: none); see
116	     *  {@link #tagsOf}. */
117	    @Transactional
118	    public Claim add(String sheetId, String user, Long personId, BigDecimal amount, LocalDate date, String note,
119	            String corrects, String ref, String tags) {
120	        Person person = person(sheetId, personId);
121	        corrects = numberOf(corrects);
