149	    /** Whether the claim form would add a claim for the person dated on a day: the person is on the
150	     *  sheet, the claim's due-by falls in no closed period and the person was not retired then. */
151	    public boolean accepts(String sheetId, Long personId, LocalDate date) {
152	        Optional<Person> found = people.findByIdAndSheetId(personId, sheetId);
