205	    /** Add a line to a DRAFT claim, counting as an edit of it: its amount becomes the quantities times
206	     *  the unit amounts of its lines added up, and CLAIM_LINE_ADDED is written ending with the line. A
207	     *  claim that is not a DRAFT, a correction, one due by a day in a closed period, one another user's
208	     *  editor locks, a blank label, a quantity below 1 or a negative unit amount, is refused. */
209	    @Transactional
210	    public Claim addLine(String sheetId, String user, Long personId, Long id, String label, int qty,
211	            BigDecimal unit) {
212	        Person person = person(sheetId, personId);
213	        sheets.lock(sheetId);
214	        Claim claim = claim(sheetId, personId, id);
215	        if (claim.getStatus() != ClaimStatus.DRAFT) {
216	            throw new ClaimNotEditableException(claim.getStatus());
217	        }
218	        refuseClosed(sheetId, claim.getDueBy());
