258	     *  sheet's today changes. A claim that is not a DRAFT, is dated in a closed period, or is locked
259	     *  by another user's editor is refused and takes no lock. */
260	    @Transactional
261	    public Claim lock(String sheetId, String user, Long personId, Long id) {
262	        person(sheetId, personId);
263	        // Lock the sheet first, so two users opening the editor at the same moment take turns.
264	        sheets.lock(sheetId);
265	        Claim claim = claims.findByIdAndSheetIdAndPersonId(id, sheetId, personId)
266	                .orElseThrow(() -> new NoSuchElementException("No claim " + id + " for person " + personId));
