281	        person(sheetId, personId);
282	        sheets.lock(sheetId);
283	        Claim claim = claims.findByIdAndSheetIdAndPersonId(id, sheetId, personId)
284	                .orElseThrow(() -> new NoSuchElementException("No claim " + id + " for person " + personId));
285	        if (user.equals(claim.getLockedBy())) {
286	            claim.setLockedBy(null);
