298	    /** Make the claims settled together one settle batch: take the sheet's next batch number and
299	     *  mark each with it. */
300	    @Transactional
301	    public long batch(String sheetId, List<Claim> settled) {
302	        long batch = sheets.nextBatchNumber(sheetId);
303	        claims.markBatch(settled.stream().map(Claim::getId).toList(), batch);
304	        settled.forEach(claim -> claim.setBatch(batch));
