308	    /** Move a claim to a new status; a change its status does not allow, or one the sheet's
309	     *  permission matrix does not let the user's role make, is refused, as is the user who opened a
310	     *  claim settling it. A clerk settling a claim whose due is above the clerk limit
311	     *  leaves it PENDING a steward's approval instead. */
312	    @Transactional
313	    public Claim changeStatus(String sheetId, String user, Long personId, Long id, ClaimStatus to) {
314	        return changeStatus(sheetId, user, personId, id, to, null);
315	    }
316	
317	    /** Move a claim to a new status, as above; a void, while the sheet's list of void reasons is not
318	     *  empty, needs a reason chosen from it, which the claim keeps and the audit line ends with. */
319	    @Transactional
320	    public Claim changeStatus(String sheetId, String user, Long personId, Long id, ClaimStatus to,
321	            String voidReason) {
322	        Person person = person(sheetId, personId);
323	        // Lock the sheet first, so a claim opened at the same moment elsewhere waits and the claim
324	        // read below is its latest state.
325	        if (to == ClaimStatus.OPEN) {
326	            sheets.lock(sheetId);
327	        }
328	        Claim claim = claim(sheetId, personId, id);
329	        settings.refuseUnless(sheetId, user, switch (to) {
330	            case OPEN -> Permission.OPEN;
331	            case SETTLED -> Permission.SETTLE;
332	            case VOID -> Permission.VOID;
333	            case DRAFT, PENDING, DELETED -> throw new StatusChangeRefusedException(claim.getStatus(), to);
334	        });
335	        refuseClosed(sheetId, claim.getDueBy());
336	        // A SETTLED claim is voided only by a steward, within the void window of its settlement.
337	        boolean reversing = to == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED;
338	        if (reversing) {
339	            refuseLateOrUnstewardedVoid(sheetId, user, claim);
340	        } else if (!claim.getStatus().canMoveTo(to)) {
341	            throw new StatusChangeRefusedException(claim.getStatus(), to);
342	        }
343	        String reason = voidReason == null || voidReason.isBlank() ? null : voidReason.trim();
344	        if (to == ClaimStatus.VOID) {
345	            refuseUnreasonedVoid(sheetId, reason);
346	        }
347	        if (to == ClaimStatus.SETTLED && claim.openedOrEditedBy(user)) {
348	            throw new OwnClaimSettleRefusedException(user);
349	        }
350	        if (to == ClaimStatus.SETTLED && claim.deferredOn(sheets.today(sheetId))) {
351	            throw new StatusChangeRefusedException(claim.getStatus(), to);
352	        }
353	        // Taken while the claim is still OPEN, so a settled due freezes in the late charge it has
354	        // gathered by then.
355	        BigDecimal due = to == ClaimStatus.SETTLED ? dueOf(sheetId, person, claim) : null;
356	        if (to == ClaimStatus.SETTLED) {
357	            refuseUnproved(sheetId, person, claim, due);
358	        }
359	        if (to == ClaimStatus.OPEN) {
360	            refuseUnnoted(sheetId, person, claim);
361	            refuseOverCap(sheetId, claim);
362	        }
363	        if (to == ClaimStatus.SETTLED && overClerkLimit(sheetId, user, due)) {
364	            to = ClaimStatus.PENDING;
365	        }
366	        claim.setStatus(to);
367	        if (to == ClaimStatus.SETTLED || to == ClaimStatus.PENDING) {
368	            // Settled one at a time until a bulk settle marks it with its batch.
369	            claim.setBatch(null);
370	        }
371	        if (to == ClaimStatus.OPEN) {
372	            claim.setNumber(nextNumber(sheetId, claim.getDueBy()));
373	            claim.setOpenedBy(user);
374	        } else if (to == ClaimStatus.SETTLED) {
375	            claim.setSettledDue(due);
376	        } else if (to == ClaimStatus.VOID) {
377	            claim.setVoidReason(reason);
378	        }
379	        Claim saved = claims.saveAndFlush(claim);
380	        log(sheetId, user, person, saved);
381	        String event = switch (to) {
382	            case OPEN -> "CLAIM_OPENED";
383	            case PENDING -> "CLAIM_PENDING";
384	            case SETTLED -> "CLAIM_SETTLED";
385	            case VOID -> "CLAIM_VOIDED";
386	            case DRAFT, DELETED -> throw new IllegalStateException("A claim is deleted or restored on its own");
387	        };
388	        String line = line(event, sheetId, user, person, saved, saved.getNumber());
389	        if (to == ClaimStatus.SETTLED) {
390	            line += " due=" + settledDueText(saved);
391	        } else if (reversing) {
392	            line += " reversed=" + settledDueText(saved);
393	        }
394	        if (to == ClaimStatus.VOID && reason != null) {
395	            line += " reason=" + reason;
396	        }
397	        audit.recordOnCommit(line);
398	        if (to == ClaimStatus.SETTLED) {
399	            notifyWatchers(sheetId, user, person, saved);
400	        }
401	        return saved;
402	    }
