404	    /** Delete a DRAFT claim: it is DELETED, counts nowhere and cannot be edited, opened or voided;
405	     *  its status log gains a DELETED line and CLAIM_DELETED is written. Any other claim, one dated in
406	     *  a closed period, or one another user's editor locks, is refused. */
407	    @Transactional
408	    public Claim delete(String sheetId, String user, Long personId, Long id) {
409	        Person person = person(sheetId, personId);
410	        sheets.lock(sheetId);
411	        Claim claim = claim(sheetId, personId, id);
412	        if (claim.getStatus() != ClaimStatus.DRAFT) {
413	            throw new DeleteRefusedException("A " + claim.getStatus() + " claim cannot be deleted");
414	        }
415	        refuseClosed(sheetId, claim.getDueBy());
416	        if (claim.lockedAgainst(user)) {
417	            throw new ClaimLockedException(claim.getLockedBy());
418	        }
419	        claim.setLockedBy(null);
420	        claim.setStatus(ClaimStatus.DELETED);
421	        Claim saved = claims.saveAndFlush(claim);
422	        log(sheetId, user, person, saved);
423	        record("CLAIM_DELETED", sheetId, user, person, saved);
424	        return saved;
425	    }
