427	    /** Restore a DELETED claim to a DRAFT, on the sheet's today it was deleted: its status log gains a
428	     *  DRAFT line and CLAIM_RESTORED is written. Any other claim, a later day, or a claim dated in a
429	     *  closed period, is refused. */
430	    @Transactional
431	    public Claim restore(String sheetId, String user, Long personId, Long id) {
432	        Person person = person(sheetId, personId);
433	        sheets.lock(sheetId);
434	        Claim claim = claim(sheetId, personId, id);
435	        if (claim.getStatus() != ClaimStatus.DELETED) {
436	            throw new DeleteRefusedException("A " + claim.getStatus() + " claim cannot be restored");
437	        }
438	        LocalDate deletedOn = logs.findByClaimIdOrderByIdAsc(claim.getId()).stream()
439	                .filter(entry -> entry.getStatus() == ClaimStatus.DELETED)
440	                .map(ClaimLogEntry::getOn)
441	                .reduce((first, last) -> last)
442	                .orElse(null);
443	        if (!sheets.today(sheetId).equals(deletedOn)) {
444	            throw new DeleteRefusedException("A claim is restored only on the day it was deleted");
445	        }
446	        refuseClosed(sheetId, claim.getDueBy());
447	        claim.setStatus(ClaimStatus.DRAFT);
448	        Claim saved = claims.saveAndFlush(claim);
449	        log(sheetId, user, person, saved);
450	        record("CLAIM_RESTORED", sheetId, user, person, saved);
451	        return saved;
452	    }
