454	    /** Defer an OPEN claim until a date after the sheet's today: until the sheet's today reaches it
455	     *  the claim counts in no total, is not overdue, cannot be settled and no statement binds it. A
456	     *  claim that is not OPEN, a date not after today, or a claim dated in a closed period, is refused. */
457	    @Transactional
458	    public Claim defer(String sheetId, String user, Long personId, Long id, LocalDate until) {
459	        Person person = person(sheetId, personId);
460	        Claim claim = claim(sheetId, personId, id);
461	        refuseClosed(sheetId, claim.getDueBy());
462	        if (claim.getStatus() != ClaimStatus.OPEN) {
463	            throw new DeferRefusedException("A " + claim.getStatus() + " claim cannot be deferred");
464	        }
465	        if (!until.isAfter(sheets.today(sheetId))) {
466	            throw new DeferRefusedException("A claim is deferred to a date after the sheet's today");
467	        }
468	        claim.setDeferredUntil(until);
469	        Claim saved = claims.saveAndFlush(claim);
470	        audit.recordOnCommit(line("CLAIM_DEFERRED", sheetId, user, person, saved, saved.getNumber())
471	                + " until=" + until);
472	        return saved;
473	    }
