479	    /** Split an amount off an OPEN claim: it keeps the rest of its amount and loses any figure a
480	     *  statement bound it to, and a new OPEN claim of the split-off amount, with the same date and
481	     *  note, the next number, opened by the user and due by its date plus the terms in force on it,
482	     *  is listed under the person naming the claim it was split from (a late entry when its due-by falls
483	     *  in a soft-closed period). A claim that is not OPEN, one
484	     *  deferred, one dated in a closed period, an amount not above 0.00 and below the claim's, or a
485	     *  user whose role may not open a claim, is refused. */
486	    @Transactional
487	    public Split split(String sheetId, String user, Long personId, Long id, BigDecimal amount) {
488	        Person person = person(sheetId, personId);
489	        // Lock the sheet first, as opening does: the new claim takes the next number.
490	        sheets.lock(sheetId);
491	        Claim claim = claim(sheetId, personId, id);
492	        settings.refuseUnless(sheetId, user, Permission.OPEN);
493	        refuseClosed(sheetId, claim.getDueBy());
494	        if (claim.getStatus() != ClaimStatus.OPEN || claim.deferredOn(sheets.today(sheetId))) {
495	            throw new SplitRefusedException("A " + claim.getStatus() + " claim cannot be split");
496	        }
497	        BigDecimal part = scaled(amount);
498	        if (part.signum() <= 0 || part.compareTo(claim.getAmount()) >= 0) {
499	            throw new SplitRefusedException("A claim is split by an amount above 0.00 and below its own");
500	        }
501	        claim.setAmount(claim.getAmount().subtract(part));
502	        claim.unbind();
503	        Claim kept = claims.saveAndFlush(claim);
504	        LocalDate on = kept.getDate();
505	        int terms = termsFor(sheetId, person, on);
506	        LocalDate dueBy = holidays.businessDaysAfter(sheetId, on, terms);
507	        Claim split = Claim.splitOff(kept, part, dueBy, terms, nextNumber(sheetId, dueBy), user);
508	        if (periods.softClosedOn(sheetId, dueBy)) {
509	            split.markLateEntry();
510	        }
511	        Claim added = claims.saveAndFlush(split);
512	        log(sheetId, user, person, added);
513	        audit.recordOnCommit(line("CLAIM_SPLIT", sheetId, user, person, kept, kept.getNumber())
514	                + " into=" + added.getNumber());
515	        record("CLAIM_OPENED", sheetId, user, person, added);
516	        return new Split(kept, added);
517	    }
