519	    /** A steward approves a PENDING claim: it is SETTLED, its due frozen at this moment. Anyone else,
520	     *  the user who opened or last edited it, or a claim that is not PENDING, is refused. */
521	    @Transactional
522	    public Claim approve(String sheetId, String user, Long personId, Long id) {
523	        Person person = person(sheetId, personId);
524	        Claim claim = pending(sheetId, user, personId, id, ClaimStatus.SETTLED);
525	        if (claim.openedOrEditedBy(user)) {
526	            throw new OwnClaimSettleRefusedException(user);
527	        }
528	        BigDecimal due = dueOf(sheetId, person, claim);
529	        refuseUnproved(sheetId, person, claim, due);
530	        claim.setSettledDue(due);
531	        claim.setStatus(ClaimStatus.SETTLED);
532	        Claim saved = claims.saveAndFlush(claim);
533	        log(sheetId, user, person, saved);
534	        audit.recordOnCommit(line("CLAIM_APPROVED", sheetId, user, person, saved, saved.getNumber())
535	                + " due=" + settledDueText(saved));
536	        notifyWatchers(sheetId, user, person, saved);
537	        return saved;
538	    }
