540	    /** Remind an OPEN or PENDING claim: REMIND is written and the claim's reminded date is the sheet's
541	     *  today. A claim in any other status, or one already reminded on the sheet's today, is refused. */
542	    @Transactional
543	    public Claim remind(String sheetId, String user, Long personId, Long id) {
544	        Person person = person(sheetId, personId);
545	        // Lock the sheet first, so two presses on the same day write one reminder.
546	        sheets.lock(sheetId);
547	        Claim claim = claim(sheetId, personId, id);
548	        LocalDate today = sheets.today(sheetId);
549	        if (!claim.getStatus().isOpen()) {
550	            throw new RemindRefusedException("A " + claim.getStatus() + " claim cannot be reminded");
551	        }
552	        if (today.equals(claim.getRemindedOn())) {
553	            throw new RemindRefusedException("The claim was already reminded on " + today);
554	        }
555	        claim.setRemindedOn(today);
556	        Claim saved = claims.saveAndFlush(claim);
557	        record("REMIND", sheetId, user, person, saved);
558	        return saved;
559	    }
