741	    /** The status logs of the sheet's claims by claim id, each oldest first, as they stood at the end
742	     *  of a day: the lines logged while the sheet's today was on or before it (null: every line). */
743	    public Map<Long, List<String>> logsOf(String sheetId, LocalDate asOf) {
744	        return logs.findBySheetIdOrderByIdAsc(sheetId).stream()
745	                .filter(entry -> asOf == null || !entry.getOn().isAfter(asOf))
746	                .collect(Collectors.groupingBy(ClaimLogEntry::getClaimId,
747	                        Collectors.mapping(ClaimLogEntry::text, Collectors.toList())));
748	    }
749	
750	    /** The status each of the sheet's claims had at the end of a day, by claim id, as its status log
751	     *  records it: the last status it moved to on or before that day. A claim added after it has none. */
752	    public Map<Long, ClaimStatus> statusesAsOf(String sheetId, LocalDate day) {
753	        Map<Long, ClaimStatus> statuses = new HashMap<>();
754	        for (ClaimLogEntry entry : logs.findBySheetIdOrderByIdAsc(sheetId)) {
755	            if (!entry.getOn().isAfter(day)) {
756	                statuses.put(entry.getClaimId(), entry.getStatus());
757	            }
758	        }
759	        return statuses;
760	    }
761	
762	    /** Log the status a claim has just moved to (or been added in): by whom, on the sheet's today, and
763	     *  its due as it is now. */
764	    private void log(String sheetId, String user, Person person, Claim claim) {
765	        BigDecimal due = dueOf(sheetId, person, claim);
766	        logs.save(new ClaimLogEntry(sheetId, claim.getId(), claim.getStatus(), user, sheets.today(sheetId),
767	                due != null ? due.toPlainString() : NO_RATE));
768	    }
769	
770	    /** A SETTLED claim is voided only by a steward, and only while the sheet's today is within
771	     *  {@value #VOID_WINDOW_DAYS} days of the date its status log last records it SETTLED. */
772	    /** While the sheet's list of void reasons is not empty, a void needs a reason from it; a reason
773	     *  not on the list is refused whatever the list holds. */
774	    private void refuseUnreasonedVoid(String sheetId, String reason) {
775	        if (reason == null ? !voidReasons.list(sheetId).isEmpty() : !voidReasons.listed(sheetId, reason)) {
776	            throw new VoidRefusedException("A void needs a reason from the sheet's list");
777	        }
778	    }
779	
780	    private void refuseLateOrUnstewardedVoid(String sheetId, String user, Claim claim) {
781	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
782	            throw new VoidRefusedException(user + " is not a steward: only a steward voids a settled claim");
783	        }
784	        LocalDate settledOn = logs.findByClaimIdOrderByIdAsc(claim.getId()).stream()
785	                .filter(entry -> entry.getStatus() == ClaimStatus.SETTLED)
786	                .map(ClaimLogEntry::getOn)
787	                .reduce((first, last) -> last)
788	                .orElseThrow(() -> new VoidRefusedException("Claim " + claim.getId() + " has no settlement"));
789	        if (sheets.today(sheetId).isAfter(settledOn.plusDays(VOID_WINDOW_DAYS))) {
790	            throw new VoidRefusedException("A settled claim is voided within " + VOID_WINDOW_DAYS
791	                    + " days of its settlement on " + settledOn);
792	        }
793	    }
794	
795	    /** The PENDING claim a steward approves or rejects; refused when it is not PENDING, dated in a
796	     *  closed period, or the user is not a steward. */
797	    private Claim pending(String sheetId, String user, Long personId, Long id, ClaimStatus to) {
798	        Claim claim = claim(sheetId, personId, id);
799	        refuseClosed(sheetId, claim.getDueBy());
800	        if (claim.getStatus() != ClaimStatus.PENDING) {
801	            throw new StatusChangeRefusedException(claim.getStatus(), to);
802	        }
803	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
804	            throw new ApprovalRefusedException(user);
805	        }
806	        return claim;
807	    }
808	
809	    private Claim claim(String sheetId, Long personId, Long id) {
810	        return claims.findByIdAndSheetIdAndPersonId(id, sheetId, personId)
811	                .orElseThrow(() -> new NoSuchElementException("No claim " + id + " for person " + personId));
812	    }
813	
814	    private static String settledDueText(Claim claim) {
815	        return claim.getSettledDue() != null ? claim.getSettledDue().toPlainString() : NO_RATE;
816	    }
817	
818	    /** The number a claim brought onto the sheet takes, as one opened now would: the sheet's next
819	     *  number for its due-by. Taken with the sheet locked. */
820	    public String numberFor(String sheetId, LocalDate dueBy) {
821	        return nextNumber(sheetId, dueBy);
822	    }
823	
824	    /** The number a claim opened now takes: under period numbering (set, and the sheet's today on or
825	     *  after it) the next within the period its due-by falls in, <period>-<n>, or X-<n> when it falls
826	     *  in none; otherwise the sheet's next sheet-wide number in the fiscal year of its due-by,
827	     *  FY<year>-<n>. Taken with the sheet locked. */
828	    private String nextNumber(String sheetId, LocalDate date) {
829	        if (!periodNumbering(sheetId)) {
830	            return sheets.nextClaimNumber(sheetId, date);
831	        }
832	        String prefix = periodPrefixOf(sheetId, date);
833	        long last = Stream.concat(claims.numbers(sheetId).stream(), claims.retiredNumbers(sheetId).stream())
834	                .filter(number -> number.startsWith(prefix))
835	                .map(number -> number.substring(prefix.length()))
836	                .filter(n -> n.matches("\\d{1,18}"))
837	                .mapToLong(Long::parseLong)
838	                .max().orElse(0);
839	        return prefix + (last + 1);
840	    }
841	
842	    /** Whether period numbering is on: set, and the sheet's today on or after it. */
843	    private boolean periodNumbering(String sheetId) {
844	        LocalDate from = settings.periodNumberingFrom(sheetId);
845	        return from != null && !sheets.today(sheetId).isBefore(from);
846	    }
847	
848	    /** The prefix a period number of a claim due by a date takes: <period>- or X-. */
849	    private String periodPrefixOf(String sheetId, LocalDate date) {
850	        return periods.findBySheetIdOrderByFromAsc(sheetId).stream()
851	                .filter(period -> period.contains(date))
852	                .findFirst().map(Period::getName).orElse(NO_PERIOD) + "-";
853	    }
854	
855	    /** The figure a claim shows: the due fixed when it was settled, else (unless it is PENDING, which
856	     *  no statement binds) the figure its person's last statement bound it to, else its due at the
857	     *  person's grade rate; null when it has none. */
858	    public BigDecimal figureOf(String sheetId, Person person, Claim claim) {
859	        return figureOf(sheetId, person, claim, null);
860	    }
861	
862	    /** The figure a claim (as it stood at the end of a day) showed then, the sheet's grades and rates
863	     *  as they stood then (null: the figure it shows now). */
864	    public BigDecimal figureOf(String sheetId, Person person, Claim claim, LocalDate asOf) {
865	        return figureOf(sheetId, person, claim, asOf, null);
866	    }
867	
868	    private BigDecimal figureOf(String sheetId, Person person, Claim claim, LocalDate asOf, RateOverride override) {
869	        if (claim.getSettledDue() != null) {
870	            return claim.getSettledDue();
871	        }
872	        return claim.isStated() && claim.getStatus() != ClaimStatus.PENDING ? claim.getStatedDue()
873	                : liveFigureOf(sheetId, person, claim, asOf, override);
874	    }
875	
876	    /** The due a claim shows: a settled claim's frozen due; otherwise the greater of the sheet's floor in
877	     *  force on its date (none for a correction) and its figure plus its late charge (none while it is
878	     *  deferred: it is not overdue then); null when it has no figure. */
879	    public BigDecimal dueOf(String sheetId, Person person, Claim claim) {
880	        return dueOf(sheetId, person, claim, null);
881	    }
882	
883	    /** The due a claim (as it stood at the end of a day) showed then: that day stands in for the
884	     *  sheet's today, and the floor, late percent, grades and rates are as they stood then (null: the
885	     *  due it shows now). */
886	    public BigDecimal dueOf(String sheetId, Person person, Claim claim, LocalDate asOf) {
887	        return dueOf(sheetId, person, claim, asOf, null);
888	    }
889	
890	    /** The due a claim would show were a grade's rate the one given on every date (null: as the rates
891	     *  stand). */
892	    private BigDecimal dueOf(String sheetId, Person person, Claim claim, LocalDate asOf, RateOverride override) {
893	        if (claim.getSettledDue() != null) {
894	            return claim.getSettledDue();
895	        }
896	        BigDecimal figure = figureOf(sheetId, person, claim, asOf, override);
897	        boolean open = claim.getStatus().isOpen() && !claim.deferredOn(todayOr(sheetId, asOf));
898	        return figure == null ? null
899	                : floored(sheetId, claim, figure.add(lateChargeOf(sheetId, person, claim, figure, open, asOf)), asOf);
900	    }
901	
902	    /** The day that stands for the sheet's today: the given one, else the sheet's today. */
903	    private LocalDate todayOr(String sheetId, LocalDate asOf) {
904	        return asOf != null ? asOf : sheets.today(sheetId);
905	    }
906	
907	    /** A due raised to the sheet's floor in force on the claim's date, unless the claim is a correction. */
908	    private BigDecimal floored(String sheetId, Claim claim, BigDecimal due, LocalDate asOf) {
909	        return claim.isCorrection() ? due : due.max(settings.floor(sheetId, claim.getDate(), asOf));
910	    }
911	
912	    /** The date a claim is overdue after: its due-by plus the grace days in force on its date for the
913	     *  person's grade in force on its date (as they stood at the end of a day; null: as they stand now). */
914	    public LocalDate overdueFrom(String sheetId, Person person, Claim claim, LocalDate asOf) {
915	        String grade = grades.gradeOn(person.getId(), claim.getDate(), asOf);
916	        return claim.getDueBy().plusDays(settings.graceFor(sheetId, grade, claim.getDate(), asOf));
917	    }
918	
919	    /** The late charge on a claim with a figure: none unless it is OPEN or PENDING and overdue (its due-by
920	     *  plus its grace, see overdueFrom, is before the sheet's today) or a correction, else the late percent of
921	     *  the figure for every 30-day boundary it is overdue past (its due-by plus its grace plus 30, 60, 90 ...
922	     *  days), compounding: the late percent in force on that boundary date of the figure plus the charges
923	     *  of the boundaries before it, rounded to two decimals as the claim's date decides (see roundingOf), the
924	     *  charges added up. Never bound by a statement: it follows the
925	     *  sheet's today. Whether the claim counts as open is given, so a re-settle can charge a SETTLED
926	     *  claim as if it were still OPEN. */
927	    private BigDecimal lateChargeOf(String sheetId, Person person, Claim claim, BigDecimal figure, boolean open,
928	            LocalDate asOf) {
929	        BigDecimal none = BigDecimal.ZERO.setScale(2);
930	        if (!open || claim.isCorrection()) {
931	            return none;
932	        }
933	        LocalDate from = overdueFrom(sheetId, person, claim, asOf);
934	        long days = ChronoUnit.DAYS.between(from, todayOr(sheetId, asOf));
935	        if (days < 30) {
936	            return none;
937	        }
938	        RoundingMode rounding = roundingOf(sheetId, claim, asOf);
939	        BigDecimal charge = none;
940	        for (long boundary = 1; boundary <= days / 30; boundary++) {
941	            BigDecimal pct = settings.latePct(sheetId, from.plusDays(30 * boundary), asOf);
942	            if (pct.signum() != 0) {
943	                charge = charge.add(figure.add(charge).multiply(pct).movePointLeft(2).setScale(2, rounding));
944	            }
945	        }
946	        return charge;
947	    }
948	
949	    /** The due on a claim at the rate in force on the claim's date for the person's grade in force
950	     *  on the claim's date: amount times rate
951	     *  divided by 100, rounded to two decimals as the claim's date decides (see roundingOf); the floor is
952	     *  not applied here (see dueOf); null when no rate applies. */
953	    private BigDecimal liveFigureOf(String sheetId, Person person, Claim claim, LocalDate asOf,
954	            RateOverride override) {
955	        BigDecimal amount = claim.getAmount();
956	        RoundingMode rounding = roundingOf(sheetId, claim, asOf);
957	        String grade = grades.gradeOn(person.getId(), claim.getDate(), asOf);
958	        Optional<BigDecimal> inForce = override != null && override.grade().equals(grade) ? Optional.of(override.rate())
959	                : rates.rateOn(sheetId, grade, claim.getDate(), asOf).map(Rate::getRate);
960	        return inForce
961	                .map(rate -> amount.multiply(rate).movePointLeft(2).setScale(2, rounding))
962	                .orElse(null);
963	    }
964	
965	    /** A grade's rate taken to apply on every date in place of the rates set for it. */
966	    private record RateOverride(String grade, BigDecimal rate) {
967	    }
968	
969	    /** What a rate preview finds: how many claims would show a different due, and the sum of the
970	     *  differences (new due minus current due). */
971	    public record RatePreview(int count, BigDecimal diff) {
972	    }
973	
974	    /** How the OPEN and PENDING claims of people on a grade (the grade in force on the claim's date)
975	     *  would change were the rate given the grade's rate on every date: how many would show a different
976	     *  due and the sum of the differences (a due of n/a counts as 0.00). A claim a statement binds keeps
977	     *  its figure. Nothing is saved. */
978	    @Transactional(readOnly = true)
979	    public RatePreview previewRate(String sheetId, String grade, BigDecimal rate) {
980	        RateOverride override = new RateOverride(grade, rate);
981	        Map<Long, Person> byId = people.findBySheetIdOrderByIdAsc(sheetId).stream()
982	                .collect(Collectors.toMap(Person::getId, person -> person));
983	        int count = 0;
984	        BigDecimal diff = BigDecimal.ZERO.setScale(2);
985	        for (Claim claim : claims.findBySheetIdOrderByListedDesc(sheetId)) {
986	            Person person = byId.get(claim.getPersonId());
987	            if (person == null || !claim.getStatus().isOpen()
988	                    || !grade.equals(grades.gradeOn(person.getId(), claim.getDate(), null))) {
989	                continue;
990	            }
991	            BigDecimal now = dueOf(sheetId, person, claim, null);
992	            BigDecimal then = dueOf(sheetId, person, claim, null, override);
993	            BigDecimal was = now == null ? BigDecimal.ZERO : now;
994	            BigDecimal will = then == null ? BigDecimal.ZERO : then;
995	            if ((now == null) != (then == null) || was.compareTo(will) != 0) {
996	                count++;
997	                diff = diff.add(will.subtract(was));
998	            }
999	        }
1000	        return new RatePreview(count, diff.setScale(2, RoundingMode.HALF_UP));
1001	    }
1002	
1003	    /** The date a claim's live figures round by: its own, or for a correction the date of the claim
1004	     *  it corrects. */
1005	    public LocalDate roundsBy(String sheetId, Claim claim) {
1006	        if (!claim.isCorrection() || claim.getCorrects() == null) {
1007	            return claim.getDate();
1008	        }
1009	        return claims.findBySheetIdAndPersonIdAndNumber(sheetId, claim.getPersonId(), claim.getCorrects())
1010	                .map(Claim::getDate).orElse(claim.getDate());
1011	    }
1012	
1013	    /** How a claim's live figures round: by the sheet's policy date against the date it rounds by. */
1014	    private RoundingMode roundingOf(String sheetId, Claim claim, LocalDate asOf) {
1015	        return settings.roundingOn(sheetId, roundsBy(sheetId, claim), asOf);
1016	    }
1017	
1018	    /** Whether a clerk is settling a claim whose due is above the sheet's clerk limit; a due of n/a
1019	     *  is within any limit, and a steward settles anything. */
1020	    private boolean overClerkLimit(String sheetId, String user, BigDecimal due) {
1021	        BigDecimal limit = settings.clerkLimit(sheetId);
1022	        if (limit == null || due == null || due.compareTo(limit) <= 0) {
1023	            return false;
1024	        }
1025	        return settings.roleOf(sheetId, user) == Role.CLERK;
1026	    }
1027	
1028	    /** A claim whose due is above the proof threshold in force on its date (its person's grade's in
1029	     *  force then when one is set, else the sheet's) cannot be settled or approved while it has no
1030	     *  proofs; a due of n/a, or no threshold, asks for none. */
1031	    private void refuseUnproved(String sheetId, Person person, Claim claim, BigDecimal due) {
1032	        String grade = grades.gradeOn(person.getId(), claim.getDate());
1033	        BigDecimal threshold = settings.proofThresholdFor(sheetId, grade, claim.getDate());
1034	        if (claim.getProofs() == 0 && threshold != null && due != null && due.compareTo(threshold) > 0) {
1035	            throw new ProofRequiredException(due, threshold);
1036	        }
1037	    }
1038	
1039	    /** A claim whose due is above the note threshold in force on its date cannot be opened while its
1040	     *  note is empty; a due of n/a, or no threshold, asks for none. */
1041	    private void refuseUnnoted(String sheetId, Person person, Claim claim) {
1042	        BigDecimal threshold = settings.noteThreshold(sheetId, claim.getDate());
1043	        if (threshold == null || (claim.getNote() != null && !claim.getNote().isBlank())) {
1044	            return;
1045	        }
1046	        BigDecimal due = dueOf(sheetId, person, claim);
1047	        if (due != null && due.compareTo(threshold) > 0) {
1048	            throw new NoteRequiredException(due, threshold);
1049	        }
1050	    }
1051	
1052	    /** A negative amount (a correction) must name the number of a SETTLED claim of the same person;
1053	     *  any other amount names none. */
1054	    private void refuseBadCorrection(String sheetId, Long personId, BigDecimal amount, String corrects) {
1055	        if (amount.signum() >= 0) {
1056	            if (corrects != null) {
1057	                throw new CorrectionRefusedException("Only a negative amount corrects a claim");
1058	            }
1059	            return;
1060	        }
1061	        if (corrects == null) {
1062	            throw new CorrectionRefusedException("A negative amount must name the claim it corrects");
1063	        }
1064	        boolean settled = claims.findBySheetIdAndPersonIdAndNumber(sheetId, personId, corrects)
1065	                .map(c -> c.getStatus() == ClaimStatus.SETTLED).orElse(false);
1066	        if (!settled) {
1067	            throw new CorrectionRefusedException("No SETTLED claim " + corrects + " of this person to correct");
1068	        }
1069	    }
1070	
1071	    /** Whether a claim on the sheet other than the given one (null: any) already uses the reference,
1072	     *  without regard to case; a null reference is never in use. */
1073	    public boolean refInUse(String sheetId, String ref, Long exceptId) {
1074	        return ref != null && claims.refInUse(sheetId, Claim.keyOf(ref), exceptId);
1075	    }
1076	
1077	    /** A reference another claim on the sheet already uses cannot be given again. */
1078	    private void refuseRefInUse(String sheetId, String ref, Long exceptId) {
1079	        if (refInUse(sheetId, ref, exceptId)) {
1080	            throw new RefInUseException("The reference " + ref + " is already used on the sheet");
1081	        }
1082	    }
1083	
1084	    /** A claim cannot be opened while its person already has as many OPEN or PENDING claims in the
1085	     *  period its due-by falls in as that period's cap. */
1086	    private void refuseOverCap(String sheetId, Claim claim) {
1087	        periods.findBySheetIdOrderByFromAsc(sheetId).stream()
1088	                .filter(period -> period.getCap() != null && period.contains(claim.getDueBy()))
1089	                .findFirst()
1090	                .ifPresent(period -> {
1091	                    if (claims.countOpenDueBetween(sheetId, claim.getPersonId(), period.getFrom(), period.getTo())
1092	                            >= period.getCap()) {
1093	                        throw new PeriodCapException(period.getName(), period.getCap());
1094	                    }
1095	                });
1096	    }
1097	
1098	    /** A claim whose due-by falls inside a closed period cannot be added, edited, opened, settled or voided. */
1099	    private void refuseClosed(String sheetId, LocalDate dueBy) {
1100	        if (periods.closedOn(sheetId, dueBy)) {
1101	            throw new PeriodClosedException("A claim due by " + dueBy + " falls in a closed period");
1102	        }
1103	    }
1104	
1105	    /** A claim dated after its person's retirement date, or after the from and before the to of a past
1106	     *  retirement of theirs, cannot be added or moved there. */
1107	    private void refuseRetired(Person person, LocalDate date) {
1108	        if (person.isRetired() && date.isAfter(person.getRetiredFrom())) {
1109	            throw new PersonRetiredException(person.getName(), person.getRetiredFrom(), date);
1110	        }
1111	        for (PersonRetirement past : retirements.findByPersonIdOrderByIdAsc(person.getId())) {
1112	            if (past.covers(date)) {
1113	                throw new PersonRetiredException(person.getName(), past.getFrom(), date);
1114	            }
1115	        }
1116	    }
1117	
1118	    private Person person(String sheetId, Long personId) {
1119	        return people.findByIdAndSheetId(personId, sheetId)
1120	                .orElseThrow(() -> new NoSuchElementException("No person " + personId + " on sheet " + sheetId));
1121	    }
1122	
1123	    /** One NOTIFY line for each user watching the claim's person, in the order they started watching. */
1124	    private void notifyWatchers(String sheetId, String user, Person person, Claim claim) {
1125	        for (PersonWatch watch : watches.findByPersonIdOrderByIdAsc(person.getId())) {
1126	            audit.recordOnCommit("NOTIFY sheet=" + sheetId + " by=" + user + " user=" + watch.getUser()
1127	                    + " person=" + person.getName() + " number=" + claim.getNumber());
1128	        }
1129	    }
1130	
1131	    private void record(String event, String sheetId, String user, Person person, Claim claim) {
1132	        record(event, sheetId, user, person, claim, claim.getNumber());
1133	    }
1134	
1135	    /** One audit line about a claim; a claim with a number carries it at the end. */
1136	    private void record(String event, String sheetId, String user, Person person, Claim claim, String number) {
1137	        audit.recordOnCommit(line(event, sheetId, user, person, claim, number));
1138	    }
1139	
1140	    private static String line(String event, String sheetId, String user, Person person, Claim claim, String number) {
1141	        return event + " sheet=" + sheetId + " by=" + user + " person=" + person.getName()
1142	                + " amount=" + claim.getAmount().toPlainString() + " date=" + claim.getDate()
1143	                + (number != null ? " number=" + number : "");
1144	    }
1145	
1146	    private static BigDecimal scaled(BigDecimal amount) {
1147	        return amount.setScale(2, RoundingMode.UNNECESSARY);
1148	    }
1149	
1150	    /** A claim number as typed: trimmed, null when blank. */
1151	    private static String numberOf(String number) {
1152	        return number == null || number.isBlank() ? null : number.trim();
1153	    }
1154	
1155	    /** Tags as typed, comma separated: each trimmed and in lower case, blanks and repeats dropped,
1156	     *  sorted. */
1157	    public static SortedSet<String> tagsOf(String tags) {
1158	        SortedSet<String> out = new TreeSet<>();
1159	        if (tags != null) {
1160	            for (String tag : tags.split(",")) {
1161	                if (!tag.isBlank()) {
1162	                    out.add(tag.trim().toLowerCase(Locale.ROOT));
1163	                }
1164	            }
1165	        }
1166	        return out;
1167	    }
1168	
1169	    /** Every tag ever used on the sheet, sorted. */
1170	    public List<String> tagsUsed(String sheetId) {
1171	        return claims.tagsUsed(sheetId);
1172	    }
1173	
1174	    /** Keep the claim's tags on the sheet's list of the tags ever used. */
1175	    private void useTags(String sheetId, Claim claim) {
1176	        claim.getTags().forEach(tag -> claims.useTag(sheetId, tag));
1177	    }
1178	
1179	    /** An external reference as typed: trimmed, null when blank. */
1180	    public static String refOf(String ref) {
1181	        return ref == null || ref.isBlank() ? null : ref.trim();
1182	    }
1183	
1184	    private static String noteOf(String note) {
1185	        return note == null ? "" : note.trim();
1186	    }
1187	
1188	    /** The terms in business days a claim of the person dated on a date takes: the person's own, else their
1189	     *  grade's in force then, else the sheet's. */
1190	    private int termsFor(String sheetId, Person person, LocalDate on) {
1191	        return person.getTerms() != null ? person.getTerms()
1192	                : settings.termsFor(sheetId, grades.gradeOn(person.getId(), on), on);
1193	    }
1194	}
